#include "physics/vehicle.hpp"
#include <cassert>
#include <cmath>
#include <iostream>
using namespace kartgib::physics;
int main(){Config c;assert(valid(c));Config bad=c;bad.mass=0;assert(!valid(bad));auto sanitized=sanitize({2,-1,5,true});assert(sanitized.throttle==1&&sanitized.brake==0&&sanitized.steer==1);auto f=forward(0),r=right(0);assert(f.z==1&&r.x==1);assert(stoppingDistance(10,c)>0);assert(steeringYawRate(10,1,c)>0);assert(suspensionForce(0.1,0,c)>0);assert(!sphereAabb({10,0,0},1,{{-1,-1,-1},{1,1,1}}).hit);auto contact=sphereAabb({1.5,0,0},1,{{-1,-1,-1},{1,1,1}});assert(contact.hit&&std::abs(contact.penetration-0.5)<1e-9);State a,b;auto t=step(a,{1,0,0,false},c,{},1.0/60);assert(t.speed>0&&a.tick==1);for(int i=0;i<599;++i)step(a,{1,0,0,false},c,{},1.0/60);assert(a.position.z>10);assert(a.forwardSpeed<=c.maxSpeed);simulate(b,std::vector<Input>(600,{1,0,0,false}),c,{},1.0/60);assert(fingerprint(a)==fingerprint(b));double before=b.forwardSpeed;for(int i=0;i<120;++i)step(b,{0,1,0,false},c,{},1.0/60);assert(b.forwardSpeed<before);State turning;for(int i=0;i<120;++i)step(turning,{1,0,0.4,false},c,{},1.0/60);assert(std::abs(turning.yaw)>0.01);State boosting;double energy=boosting.boostEnergy;step(boosting,{1,0,0,true},c,{},1.0/60);assert(boosting.boostEnergy<energy);auto wheel=wheelPose(boosting,c,0);assert(std::isfinite(wheel.position.x));State colliding;colliding.position={1.5,0,0};resolveContact(colliding,contact);assert(colliding.position.x>1.5);bool rejected=false;try{step(a,{},c,{},0);}catch(const std::invalid_argument&){rejected=true;}assert(rejected);std::cout<<"VEHICLE_PHYSICS_PASS deterministic=1 ticks=600 collisions=1\n";}
